import "./FirstAdoptionInfoContainer.css";

const FirstAdoptionInfoContainer = () => {
  return (
    <div className="adopt-info-section">
      <h3 className="adopt-info-title">Thank You for Choosing Rafeeq!</h3>
      <p className="adopt-info-paragraph">
        Here in Rafeeq, we are passionate about creating a world where every pet
        finds the loving home they deserve. <br />
        Adoption is not just about giving an animal a place to stay; it's about
        building a bond of unconditional love and companionship that lasts a
        lifetime. Our platform is designed to make your pet adoption journey as
        smooth and rewarding as possible. Whether you're looking for a playful
        puppy, a cuddly kitten, or a calm senior companion, we're here to help
        you find your perfect match. <br />
        By choosing to adopt, you’re not just changing a pet’s life, you’re
        enriching your own. Let us guide you toward your new best friend and a
        lifetime of unforgettable memories.
      </p>
    </div>
  );
};

export default FirstAdoptionInfoContainer;
